const REGION_BY_DISTRICT = new Map(KARNATAKA_DISTRICTS.map((d) => [d.name, d.region]));

/** Tourist places of Karnataka, region taken from the district so the two never disagree. */
export const KARNATAKA_PLACES: KarnatakaPlace[] = ROWS.map(([id, name, district, categories, blurb, aliases]) => ({
  id,
  name,
  aliases: aliases ?? [],
  district,
  region: REGION_BY_DISTRICT.get(district) ?? "Bengaluru & surroundings",
  categories,
  blurb,
}));
